9	func TestLooksLikeULID(t *testing.T) {
10		t.Parallel()
11		tests := []struct {
12			in   string
13			want bool
14		}{
15			{in: "REDACTED", want: true}, // 26 chars, valid alphabet
16			{in: "REDACTED", want: true}, // lowercase accepted
17			{in: "acme", want: false},                      // short name
18			{in: "my-project", want: false},                // hyphen not in alphabet
19			{in: "", want: false},                          // empty
20			{in: "01J0ABCDEFGHJKMNPQRSTVWXY", want: false}, // 25 chars
21			{in: "REDACTED", want: false},
22			{in: "REDACTED", want: false}, // contains I
23			{in: "REDACTED", want: false}, // contains L
24			{in: "REDACTED", want: false}, // contains O
25			{in: "REDACTED", want: false}, // contains U
26		}
27		for _, tt := range tests {
28			t.Run(tt.in, func(t *testing.T) {
29				t.Parallel()
30				if got := looksLikeULID(tt.in); got != tt.want {
31					t.Errorf("looksLikeULID(%q) = %v, want %v", tt.in, got, tt.want)
32				}
33			})
34		}
35	}
36	
37	func TestParseQualifiedHandle(t *testing.T) {
38		t.Parallel()
39		tests := []struct {
40			in           string
41			wantProvider string
42			wantHandle   string
43			wantErr      bool
44		}{
45			{in: "github:alice", wantProvider: "github", wantHandle: "alice"},
46			{in: "github:alice:bob", wantProvider: "github", wantHandle: "alice:bob"}, // only first colon splits
47			{in: "alice", wantErr: true},                                              // no provider prefix
48			{in: "github:", wantErr: true},                                            // empty handle
49			{in: ":alice", wantErr: true},                                             // empty provider
50			{in: "", wantErr: true},
51		}
52		for _, tt := range tests {
53			t.Run(tt.in, func(t *testing.T) {
54				t.Parallel()
55				provider, handle, err := parseQualifiedHandle(tt.in)
56				if tt.wantErr {
57					if err == nil {
58						t.Errorf("parseQualifiedHandle(%q) expected error", tt.in)
59					}
60					return
61				}
62				if err != nil {
63					t.Fatalf("parseQualifiedHandle(%q): %v", tt.in, err)
64				}
65				if provider != tt.wantProvider || handle != tt.wantHandle {
66					t.Errorf("parseQualifiedHandle(%q) = (%q, %q), want (%q, %q)", tt.in, provider, handle, tt.wantProvider, tt.wantHandle)
67				}
68			})
69		}
70	}
71	
72	func TestPickOrg(t *testing.T) {
73		t.Parallel()
74		orgs := []coreapi.Org{
75			{ID: "01J0ORG0000000000000000001", Name: "acme"},
76			{ID: "01J0ORG0000000000000000002", Name: "globex"},
77		}
78	
79		t.Run("unique match", func(t *testing.T) {
80			t.Parallel()
81			got, err := pickOrg(orgs, "globex")
82			if err != nil {
83				t.Fatalf("pickOrg: %v", err)
84			}
85			if got != "01J0ORG0000000000000000002" {
86				t.Errorf("pickOrg = %q, want globex id", got)
87			}
88		})
89	
90		t.Run("no match", func(t *testing.T) {
91			t.Parallel()
92			if _, err := pickOrg(orgs, "missing"); err == nil {
93				t.Error("pickOrg expected error for unknown name")
94			}
95		})
96	
97		t.Run("ambiguous", func(t *testing.T) {
98			t.Parallel()
99			dupes := []coreapi.Org{
100				{ID: "01J0ORG000000000000000000A", Name: "dup"},
101				{ID: "01J0ORG000000000000000000B", Name: "dup"},
102			}
103			if _, err := pickOrg(dupes, "dup"); err == nil {
104				t.Error("pickOrg expected error for ambiguous name")
105			}
106		})
107	}
108	
109	func TestPickProject(t *testing.T) {
110		t.Parallel()
111		projects := []coreapi.Project{
112			{ID: "01J0PRJ0000000000000000001", Name: "widgets", OwnerId: "01J0ORG0000000000000000001"},
113			{ID: "01J0PRJ0000000000000000002", Name: "gadgets", OwnerId: "01J0ORG0000000000000000001"},
114		}
115	
116		t.Run("unique match", func(t *testing.T) {
117			t.Parallel()
118			got, err := pickProject(projects, "gadgets")
119			if err != nil {
120				t.Fatalf("pickProject: %v", err)
121			}
122			if got != "01J0PRJ0000000000000000002" {
123				t.Errorf("pickProject = %q, want gadgets id", got)
124			}
125		})
126	
127		t.Run("no match", func(t *testing.T) {
128			t.Parallel()
129			if _, err := pickProject(projects, "missing"); err == nil {
130				t.Error("pickProject expected error for unknown name")
131			}
132		})
133	
134		t.Run("ambiguous across owners", func(t *testing.T) {
135			t.Parallel()
136			dupes := []coreapi.Project{
137				{ID: "01J0PRJ000000000000000000A", Name: "shared", OwnerId: "01J0ORG0000000000000000001"},
138				{ID: "01J0PRJ000000000000000000B", Name: "shared", OwnerId: "01J0ORG0000000000000000002"},
139			}
140			if _, err := pickProject(dupes, "shared"); err == nil {
141				t.Error("pickProject expected error for ambiguous name")
142			}
143		})
144	}
145	
146	func TestFilterProjectsByName(t *testing.T) {
147		t.Parallel()
148		projects := []coreapi.Project{
149			{ID: "1", Name: "a"},
150			{ID: "2", Name: "b"},
151			{ID: "3", Name: "a"},
152		}
153	
154		t.Run("empty name returns all", func(t *testing.T) {
155			t.Parallel()
156			if got := filterProjectsByName(projects, ""); len(got) != 3 {
157				t.Errorf("len = %d, want 3", len(got))
158			}
159		})
160	
161		t.Run("exact filter", func(t *testing.T) {
162			t.Parallel()
163			got := filterProjectsByName(projects, "a")
164			if len(got) != 2 {
165				t.Fatalf("len = %d, want 2", len(got))
166			}
167			for _, p := range got {
168				if p.Name != "a" {
169					t.Errorf("unexpected project %q", p.Name)
170				}
171			}
172		})
173	
174		t.Run("no match", func(t *testing.T) {
175			t.Parallel()
176			if got := filterProjectsByName(projects, "z"); len(got) != 0 {
177				t.Errorf("len = %d, want 0", len(got))
178			}
